pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Respons contains standings groups", function () {
    const jsonData = pm.response.json();

    pm.expect(jsonData).to.have.property("groups");
    pm.expect(jsonData.groups).to.be.an("array");
    pm.expect(jsonData.groups.length).to.be.above(0);
});

pm.test("Standings groups contain teams", function () {
    const jsonData = pm.response.json();

    jsonData.groups.forEach((group) => {
        pm.expect(group).to.have.property("name");
        pm.expect(group.name).to.be.a("string");

        pm.expect(group.standings).to.be.an("array");
        pm.expect(group.standings.length).to.be.above(0);
    });
});

pm.test("Team standings contain valid statistics", function () {
    const jsonData = pm.response.json();

    jsonData.groups.forEach((group) => {
        group.standings.forEach((standing) => {
            pm.expect(standing.team).to.have.property("id");
            pm.expect(standing.team).to.have.property("name");
            pm.expect(standing.wins).to.be.a("number");
            pm.expect(standing.loses).to.be.a("number");
            pm.expect(standing.position).to.be.a("number");
        });
    });
});

